/**
 * Encapsulates state within a closure.
 */
function createCounter(initialValue = 0, step = 1) {
  let count = initialValue;
  return {
    increment() {
      count += step;
      return count;
    },
    decrement() {
      count -= step;
      return count;
    },
    getValue() {
      return count;
    },
    reset() {
      count = initialValue;
      return count;
    }
  };
}
